import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int A = fs.nextInt();
        int B = fs.nextInt();

        int[] SA = new int[A];
        for (int i = 0; i < A; i++) {
            SA[i] = fs.nextInt();
        }

        int j = 0;
        for (int i = 0; i < B; i++) {
            int y = fs.nextInt();

            while (j < A && SA[j] != y) {
                j++;
            }

            if (j == A) {
                System.out.println("N");
                return;
            }

            j++;
        }

        System.out.println("S");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c != -1 && c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = readByte();
            }

            return val * sign;
        }
    }
}
